SELECT 
FROM sal_yt_order_sub_receive
WHERE is_deleted = 0

    AND id = #{id}


    AND order_sub_id = #{orderSubId}


    AND amount = #{amount}


    AND currency = #{currency}

-- SELECT s.*, -- (select nick_name from sys_user where user_id = s.create_user ) as createUserName -- FROM sal_yt_order_sub_receive s -- LEFT JOIN sal_yt_order_sub sos ON s.order_sub_id = sos.id -- LEFT JOIN sal_yt_order so ON sos.order_id = so.id -- WHERE s.is_deleted = 0 AND sos.is_deleted = 0 AND so.is_deleted = 0 and s.order_sub_id={orderSubId} SELECT s.*, (select nick_name from sys_user where user_id = s.create_user ) as createUserName FROM sal_yt_order_sub_receive s LEFT JOIN sal_yt_order so ON s.order_id = so.id WHERE s.is_deleted = 0 AND so.is_deleted = 0 and s.order_id=#{orderSubId}
AND so.code LIKE CONCAT('%', #{subCode}, '%')
AND so.platform_order_code LIKE CONCAT('%', #{platformOrderCode}, '%')
AND so.platform = #{platform}
AND so.sales_employee_name LIKE CONCAT('%', #{salesEmployeeName}, '%')
ORDER BY s.create_time DESC

select *
from sal_yt_order_sub_receive
where order_id=#{orderId}
and amount=#{receiveAmount}
and third_receive_time=#{receiveTime}
and currency=#{currency}
and create_user=#{createUser}
and is_deleted=0
